import { existsSync } from 'node:fs';
import path from 'node:path';
import { androidAppGradle, androidManifest, infoPlist } from '../native.js';
import { addPlistArrayString, removePlistArrayString } from './plist.js';

// Edit factories shared by the recipes. An edit is:
// {
//   id,                       same id in two recipes = the same change (undo keeps it while the other needs it)
//   packages,                 the packages it sets up: undo keeps the edit while your code still uses them
//   platform,                 'android' | 'ios': only when that folder exists and isn't generated by Expo
//                             'expo': only in Expo projects whose native folders are generated (app.json)
//                             undefined: JS-side files (babel.config.js, tsconfig.json, package.json, ...)
//   description, manual,      what it does, and how to do it by hand
//   find(root, ctx),          the file to change, or null
//   optional,                 true (or a function of ctx): no file means nothing to do, not "do by hand"
//   apply(content, file, ctx) new content; the same content when already done; null when the file looks unfamiliar
//   undo(content, file, ctx) the content without the change; null when that's not safe (undo by hand)
// }

export function projectFile(...names) {
  return (root) => names.map((name) => path.join(root, name)).find((file) => existsSync(file)) ?? null;
}

// --- JSON files (package.json, tsconfig.json, app.json) ---------------------------------

// Parses, lets `change(data)` modify it, and prints it back with the file's indentation.
// `change` returns false when the file looks unfamiliar. Comments in JSON (tsconfig allows them) → null.
export function editJson(content, change) {
  let data;
  try {
    data = JSON.parse(content);
  } catch {
    return null;
  }
  if (change(data) === false) return null;
  const indent = /^\{\s*\n([ \t]+)"/.exec(content)?.[1] ?? '  ';
  const next = JSON.stringify(data, null, indent) + (content.endsWith('\n') ? '\n' : '');
  return JSON.stringify(JSON.parse(content)) === JSON.stringify(data) ? content : next;
}

// --- AndroidManifest.xml ----------------------------------------------------------------

// <uses-permission> lines, added after the last existing one (or after <manifest ...>).
export function addUsesPermissions(content, lines) {
  const missing = lines.filter((line) => !content.includes(`android:name="${permissionName(line)}"`));
  if (missing.length === 0) return content;
  const existing = [...content.matchAll(/^([ \t]*)<uses-permission\b[^\n]*\n/gm)].at(-1);
  if (existing) {
    const at = existing.index + existing[0].length;
    return content.slice(0, at) + missing.map((line) => `${existing[1]}${line}\n`).join('') + content.slice(at);
  }
  const manifest = /<manifest\b[^>]*>[ \t]*\n/.exec(content);
  if (!manifest) return null;
  const at = manifest.index + manifest[0].length;
  return `${content.slice(0, at)}\n${missing.map((line) => `    ${line}\n`).join('')}${content.slice(at)}`;
}

export function removeUsesPermissions(content, lines) {
  let result = content;
  for (const line of lines) {
    result = result.replace(new RegExp(`^[ \\t]*${escape(line)}[ \\t]*\\n`, 'm'), '');
  }
  return result;
}

function permissionName(line) {
  return /android:name="([^"]+)"/.exec(line)[1];
}

export function manifestFile(root) {
  return androidManifest(root);
}

// --- android/app/build.gradle ----------------------------------------------------------

// Adds a line after the last `apply plugin:` line at the top of android/app/build.gradle.
export function addAfterApplyPlugin(content, line) {
  if (content.includes(line)) return content;
  const applies = [...content.matchAll(/^apply plugin:[^\n]*\n/gm)];
  if (applies.length === 0) return null;
  const last = applies.at(-1);
  const at = last.index + last[0].length;
  return content.slice(0, at) + line + '\n' + content.slice(at);
}

export function removeLine(content, line) {
  return content.replace(new RegExp(`^${escape(line)}[ \\t]*\\n`, 'm'), '');
}

export function appGradle(root) {
  // Kotlin DSL (build.gradle.kts) uses a different syntax: the user does that by hand.
  const file = androidAppGradle(root);
  return file?.endsWith('.gradle') ? file : null;
}

// --- Info.plist font list (icons) --------------------------------------------------------

export function plistFonts(fonts) {
  return {
    find: (root) => infoPlist(root),
    apply: (content) => fonts.reduce((result, font) => result && addPlistArrayString(result, 'UIAppFonts', font), content),
    undo: (content) => fonts.reduce((result, font) => removePlistArrayString(result, 'UIAppFonts', font), content),
  };
}

// --- .gitignore ---------------------------------------------------------------------------

export function addGitignoreLine(content, line, comment) {
  const lines = content.split('\n').map((text) => text.trim());
  if (lines.includes(line) || lines.includes(`/${line}`)) return content;
  const separator = content === '' || content.endsWith('\n\n') ? '' : content.endsWith('\n') ? '\n' : '\n\n';
  return `${content}${separator}# ${comment}\n${line}\n`;
}

export function escape(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}
